import unittest

from solution import restore_session


class RestoreSessionTests(unittest.TestCase):
    def test_adds_default_theme_when_absent(self):
        state = {"version": 3, "preferences": {"language": "en"}, "tokens": [1, 2]}
        result = restore_session(state)
        self.assertEqual(result, {
            "version": 3,
            "preferences": {"language": "en", "theme": "system"},
            "tokens": [1, 2],
        })
        self.assertEqual(state, {
            "version": 3,
            "preferences": {"language": "en"},
            "tokens": [1, 2],
        })

    def test_preserves_existing_theme_even_if_falsy(self):
        for theme in ["dark", "", None, False]:
            state = {"version": 1, "preferences": {"theme": theme}}
            result = restore_session(state)
            self.assertIn("theme", result["preferences"])
            self.assertEqual(result["preferences"]["theme"], theme)

    def test_deep_copy_preserves_internal_aliases(self):
        shared = {"values": []}
        state = {
            "version": 8,
            "preferences": {"nested": shared},
            "cache": shared,
            "other": [shared],
        }
        result = restore_session(state)
        self.assertIsNot(result, state)
        self.assertIsNot(result["preferences"], state["preferences"])
        self.assertIsNot(result["cache"], shared)
        self.assertIs(result["preferences"]["nested"], result["cache"])
        self.assertIs(result["other"][0], result["cache"])
        self.assertIsNot(result["cache"]["values"], shared["values"])
        result["cache"]["values"].append("output")
        self.assertEqual(shared["values"], [])
        shared["values"].append("input")
        self.assertEqual(result["cache"]["values"], ["output"])

    def test_accepts_zero_and_negative_integer_versions(self):
        for version in [0, -1, 10**30]:
            with self.subTest(version=version):
                result = restore_session({"version": version, "preferences": {}})
                self.assertEqual(result["version"], version)

    def test_invalid_state_and_field_types(self):
        cases = [
            None,
            [],
            {},
            {"version": 1},
            {"preferences": {}},
            {"version": True, "preferences": {}},
            {"version": False, "preferences": {}},
            {"version": 1.0, "preferences": {}},
            {"version": "1", "preferences": {}},
            {"version": 1, "preferences": []},
            {"version": 1, "preferences": None},
        ]
        for state in cases:
            with self.subTest(state=state):
                with self.assertRaises(TypeError):
                    restore_session(state)


if __name__ == "__main__":
    unittest.main()

